#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *s1 = argv[1];
    const char *s2 = argv[2];
    size_t len1 = strlen(s1);
    size_t len2 = strlen(s2);
    if (len1 > 0x40 || len2 > 0x40) { // 64 characters max
        puts("TOO_LONG");
        return 0;
    }
    // DP table of size (len1+1) x (len2+1), max 65x65
    int dp[0x41][0x41];
    for (size_t i = 0; i <= len1; ++i) dp[i][0] = (int)i;
    for (size_t j = 0; j <= len2; ++j) dp[0][j] = (int)j;
    for (size_t i = 1; i <= len1; ++i) {
        for (size_t j = 1; j <= len2; ++j) {
            if (s1[i-1] == s2[j-1]) {
                dp[i][j] = dp[i-1][j-1];
            } else {
                int del = dp[i-1][j] + 1;   // deletion
                int ins = dp[i][j-1] + 1;   // insertion
                int sub = dp[i-1][j-1] + 1; // substitution
                int m = del;
                if (ins < m) m = ins;
                if (sub < m) m = sub;
                dp[i][j] = m;
            }
        }
    }
    printf("%d\n", dp[len1][len2]);
    return 0;
}
